const int ledPin = 13;
unsigned long previous = 0;
bool ledOn = false;

void setup() {
  pinMode(ledPin, OUTPUT);
}

void loop() {
  if (millis() - previous >= 250) {
    previous = millis();
    ledOn = !ledOn;
    digitalWrite(ledPin, ledOn);
  }
}

